  addCum("abstractalg", "aa2", [{"type":"regular","q":"In a group of order 40, can a subgroup have order 15?","answer":"No","solution":"15 does not divide 40."},{"type":"regular","q":"If H ≤ G and |H| = 7, |G| = 28, how many left cosets of H exist?","answer":"4","solution":"[G:H] = |G|/|H| = 28/7 = 4."},{"type":"word","q":"A group of order 18 has a normal subgroup of order 3. What is the order of the quotient group?","answer":"6","solution":"|G/N| = |G|/|N| = 18/3 = 6."},{"type":"regular","q":"In ℤ/12ℤ, the subgroup ⟨4⟩ has order 3. How many left cosets does it have?","answer":"4","solution":"[ℤ/12ℤ : ⟨4⟩] = 12/3 = 4."},{"type":"regular","q":"Is the subgroup of rotations in the dihedral group D₆ normal?","answer":"Yes","solution":"In dihedral groups, the rotation subgroup is always normal."},{"type":"word","q":"A researcher partitions a group of order 32 into cosets of a subgroup, obtaining 8 cosets. What is the subgroup order?","answer":"4","solution":"|H| = |G|/[G:H] = 32/8 = 4."},{"type":"regular","q":"If G is abelian and N ≤ G, is N normal in G?","answer":"Yes","solution":"In abelian groups, all subgroups are normal."},{"type":"regular","q":"Can a group of order 21 have a subgroup of order 8?","answer":"No","solution":"8 does not divide 21."},{"type":"word","q":"In the symmetric group S₅, the alternating group A₅ is normal. If |S₅| = 120, what is |S₅/A₅|?","answer":"2","solution":"|S₅/A₅| = |S₅|/|A₅| = 120/60 = 2."},{"type":"regular","q":"If an element has order 6 in a group, what is the maximum order of the group?","answer":"Cannot determine","solution":"The group order must be divisible by 6, but no upper bound is set."},{"type":"regular","q":"What is the order of the quotient group (ℤ/20ℤ)/(⟨5⟩)?","answer":"5","solution":"|⟨5⟩| = 4 in ℤ/20ℤ, so the quotient has order 20/4 = 5."},{"type":"word","q":"A group G of order 48 has a normal subgroup N with |N| = 12. Is the quotient group cyclic?","answer":"Cannot determine","solution":"The quotient has order 4, but its structure depends on G."},{"type":"regular","q":"In a cyclic group of order 30, how many subgroups of order 5 exist?","answer":"1","solution":"Cyclic groups have exactly one subgroup of each divisor order."},{"type":"regular","q":"If N ◁ G with |G| = 24 and |G/N| = 3, what is |N|?","answer":"8","solution":"|N| = |G|/|G/N| = 24/3 = 8."},{"type":"word","q":"In the Klein four-group V₄, every non-identity element has order 2. Is V₄ abelian, and are all its subgroups normal?","answer":"Yes to both","solution":"V₄ is abelian (all elements commute), so all subgroups are normal."},{"type":"regular","q":"Can a group of order 14 have a non-trivial proper subgroup of order 6?","answer":"No","solution":"6 does not divide 14."},{"type":"word","q":"A group has 60 elements. A normal subgroup has 12 elements. How many elements are in the quotient group?","answer":"5","solution":"|G/N| = |G|/|N| = 60/12 = 5."},{"type":"regular","q":"If H is a subgroup of index 3 in G, is H normal?","answer":"No, not necessarily","solution":"Index 2 guarantees normality, but index 3 does not."},{"type":"regular","q":"In the quaternion group Q₈ of order 8, what are the possible orders of elements?","answer":"1, 2, 4","solution":"By Lagrange, element orders divide 8; Q₈ has elements of orders 1, 2, and 4."},{"type":"word","q":"A cyclic group of order 45 is partitioned into cosets of a subgroup. If each coset has 9 elements, how many cosets are there?","answer":"5","solution":"Number of cosets = 45/9 = 5."},{"type":"regular","q":"Is the center Z(D₃) a normal subgroup of D₃?","answer":"Yes","solution":"The center is always normal in any group."},{"type":"regular","q":"If φ: G → H is a surjective homomorphism and |G| = 36, |ker(φ)| = 4, what is |H|?","answer":"9","solution":"By the first isomorphism theorem, |H| = |G|/|ker(φ)| = 36/4 = 9."},{"type":"word","q":"A group of order 50 has a normal subgroup of order 10. The quotient group has order 5. Does this satisfy all divisibility conditions?","answer":"Yes","solution":"10 divides 50, and 50/10 = 5."}]);
  add("abstractalg", "aa3", 0, [{"type":"regular","q":"If φ: G → H is a group homomorphism and g ∈ G, what is φ(g^{-1})?","answer":"φ(g)^{-1}","solution":"Since φ(g) φ(g^{-1}) = φ(gg^{-1}) = φ(e) = e_H, we have φ(g^{-1}) = φ(g)^{-1}."},{"type":"regular","q":"Is φ: ℝ^* → ℝ^*, x ↦ x² a group homomorphism under multiplication?","answer":"Yes","solution":"φ(xy) = (xy)² = x²y² = φ(x)φ(y) for all x, y ∈ ℝ^*."},{"type":"regular","q":"If ker(φ) = {e}, what can you conclude about φ?","answer":"φ is injective","solution":"A homomorphism is injective if and only if its kernel is trivial."},{"type":"regular","q":"Find ker(φ) where φ: ℤ → ℤ_5 is given by φ(n) = n mod 5.","answer":"5ℤ","solution":"The kernel consists of all integers n such that n ≡ 0 (mod 5), which is the ideal 5ℤ."},{"type":"regular","q":"If φ: G → H is a homomorphism and |G| is finite, what divides |im(φ)|?","answer":"|G|","solution":"By Lagrange's theorem applied to the quotient structure, |G| = |ker(φ)| · |im(φ)|."},{"type":"regular","q":"Is the determinant map det: GL_n(ℝ) → ℝ^* a group homomorphism?","answer":"Yes","solution":"det(AB) = det(A)det(B) for all matrices A, B ∈ GL_n(ℝ)."},{"type":"regular","q":"What is the image of the homomorphism φ: ℤ → ℤ_7, n ↦ 3n mod 7?","answer":"ℤ_7","solution":"Since gcd(3, 7) = 1, the element 3 generates ℤ_7, so im(φ) = ℤ_7."},{"type":"word","q":"A company has a group G of 12 employees. A homomorphism φ maps G to a group H of authorized access levels. If the kernel has 3 elements, how many distinct access levels are assigned?","answer":"4","solution":"By the first isomorphism theorem, |im(φ)| = |G| / |ker(φ)| = 12 / 3 = 4."},{"type":"word","q":"A cryptographic function φ encrypts messages from group G (order 20) to group H. If exactly 5 messages map to the same ciphertext, what is |ker(φ)|?","answer":"5","solution":"Each element of the image has exactly |ker(φ)| preimages, so |ker(φ)| = 5."},{"type":"word","q":"In a group of rotations, a homomorphism φ records the angle rotated. If two rotations give the same angle, what property does φ lack?","answer":"Injectivity","solution":"A homomorphism is injective if and only if distinct elements map to distinct images."},{"type":"regular","q":"If φ: G → H is a homomorphism, is φ(e_G) = e_H?","answer":"Yes","solution":"φ(e_G) = φ(e_G · e_G) = φ(e_G)φ(e_G), so φ(e_G) = e_H."},{"type":"regular","q":"For φ: ℤ_6 → ℤ_6, n ↦ 2n, what is the image?","answer":"{0, 2, 4}","solution":"The image is {0, 2, 4, 0, 2, 4} = {0, 2, 4}, which is the subgroup of order 3."},{"type":"regular","q":"Is the map φ: (ℤ, +) → (ℤ, +), n ↦ n + 1 a homomorphism?","answer":"No","solution":"φ(0 + 0) = 1 but φ(0) + φ(0) = 2, so the homomorphism property fails."},{"type":"word","q":"A quality control process uses a homomorphism from a group of 15 products to a group of 3 quality grades. What is the minimum size of the kernel?","answer":"5","solution":"By the first isomorphism theorem, |ker(φ)| = |G| / |im(φ)| ≥ 15 / 3 = 5."},{"type":"word","q":"A network routing protocol uses a homomorphism from a group of packet types to a group of destinations. If the kernel is trivial, what is guaranteed about the routing?","answer":"Each packet type routes to a unique destination (injectivity)","solution":"A trivial kernel means the homomorphism is injective, so distinct packets map to distinct destinations."}]);
  add("abstractalg", "aa3", 1, [{"type":"regular","q":"Are ℤ_8 and ℤ_2 × ℤ_4 isomorphic?","answer":"No","solution":"ℤ_8 is cyclic of order 8, while ℤ_2 × ℤ_4 has exponent 4, so they cannot be isomorphic."},{"type":"regular","q":"Are ℤ_3 × ℤ_5 and ℤ_15 isomorphic?","answer":"Yes","solution":"By the Chinese Remainder Theorem, since gcd(3, 5) = 1, ℤ_3 × ℤ_5 ≅ ℤ_15."},{"type":"regular","q":"If G ≅ H, what can you say about their centers Z(G) and Z(H)?","answer":"Z(G) ≅ Z(H)","solution":"Isomorphisms preserve the center structure, so the centers are isomorphic."},{"type":"regular","q":"How many non-isomorphic abelian groups of order 8 exist?","answer":"3","solution":"The abelian groups of order 8 are ℤ_8, ℤ_4 × ℤ_2, and ℤ_2 × ℤ_2 × ℤ_2."},{"type":"regular","q":"If φ: G → H is an isomorphism and g ∈ G has order n, what is the order of φ(g)?","answer":"n","solution":"Isomorphisms preserve element orders: φ(g)^n = φ(g^n) = φ(e) = e, and n is minimal."},{"type":"regular","q":"Are S_3 and ℤ_6 isomorphic?","answer":"No","solution":"S_3 is non-abelian while ℤ_6 is abelian, so they cannot be isomorphic."},{"type":"regular","q":"Is there an isomorphism from ℚ to ℤ?","answer":"No","solution":"ℚ is divisible (every element is divisible by 2), but ℤ is not, so they are not isomorphic."},{"type":"regular","q":"If G ≅ H and G is cyclic, is H cyclic?","answer":"Yes","solution":"Isomorphisms preserve the property of being cyclic."},{"type":"word","q":"Two companies model their organizational structures as groups of order 12. Company A's structure is cyclic. Can Company B's non-abelian structure of order 12 be isomorphic to Company A's?","answer":"No","solution":"Isomorphic groups must have the same algebraic properties; a cyclic group cannot be isomorphic to a non-abelian group."},{"type":"word","q":"A mathematician claims that two permutation groups of the same order 6 must be isomorphic. Is this claim true?","answer":"No","solution":"S_3 (non-abelian) and ℤ_6 (abelian) both have order 6 but are not isomorphic."},{"type":"regular","q":"How many non-isomorphic groups of order 6 exist?","answer":"2","solution":"The groups of order 6 are ℤ_6 (cyclic) and S_3 (non-abelian dihedral)."},{"type":"regular","q":"If |G| = |H| and both are abelian of prime order p, are G and H isomorphic?","answer":"Yes","solution":"All groups of prime order are cyclic, and all cyclic groups of the same order are isomorphic."},{"type":"word","q":"A database system uses two isomorphic group structures for encryption. If one structure has an element of order 7, what orders must exist in the other?","answer":"7","solution":"Isomorphisms preserve element orders, so the other structure must also have an element of order 7."},{"type":"word","q":"Two networks are modeled as groups. Network A is ℤ_2 × ℤ_3 and Network B is ℤ_6. Are their topologies isomorphic?","answer":"Yes","solution":"By the Chinese Remainder Theorem, ℤ_2 × ℤ_3 ≅ ℤ_6 since gcd(2, 3) = 1."},{"type":"regular","q":"If φ: G → H is an isomorphism, is φ^{-1}: H → G also a homomorphism?","answer":"Yes","solution":"The inverse of an isomorphism is always a homomorphism (and also an isomorphism)."}]);
  add("abstractalg", "aa3", 2, [{"type":"regular","q":"State the First Isomorphism Theorem for groups.","answer":"If φ: G → H is a surjective homomorphism, then G/ker(φ) ≅ H.","solution":"The quotient of G by the kernel is isomorphic to the image of φ."},{"type":"regular","q":"If φ: G → H is a homomorphism, what is the relationship between |G|, |ker(φ)|, and |im(φ)|?","answer":"|G| = |ker(φ)| · |im(φ)|","solution":"This follows from the First Isomorphism Theorem and Lagrange's theorem."},{"type":"regular","q":"For φ: ℤ → ℤ_n, n ↦ n mod m where m | n, what is G/ker(φ)?","answer":"ℤ_m","solution":"By the First Isomorphism Theorem, ℤ/mℤ ≅ ℤ_m."},{"type":"regular","q":"If φ: G → H is a homomorphism with ker(φ) = {e}, what does the First Isomorphism Theorem tell us?","answer":"G ≅ im(φ)","solution":"When the kernel is trivial, G/ker(φ) = G, so G ≅ im(φ)."},{"type":"regular","q":"Let φ: S_3 → ℤ_2 be the homomorphism sending even permutations to 0 and odd to 1. What is ker(φ)?","answer":"A_3 (the alternating group)","solution":"The kernel consists of all permutations mapping to 0, which are exactly the even permutations."},{"type":"regular","q":"If φ: G → H is a surjective homomorphism and |G| = 12, |ker(φ)| = 3, what is |H|?","answer":"4","solution":"By the First Isomorphism Theorem, |H| = |im(φ)| = |G|/|ker(φ)| = 12/3 = 4."},{"type":"regular","q":"For the determinant homomorphism det: GL_n(ℝ) → ℝ^*, what is ker(det)?","answer":"SL_n(ℝ) (special linear group)","solution":"The kernel consists of all matrices with determinant 1."},{"type":"regular","q":"If N is a normal subgroup of G and φ: G → G/N is the natural quotient map, what is ker(φ)?","answer":"N","solution":"The kernel of the quotient map is exactly the normal subgroup we are quotienting by."},{"type":"word","q":"A communication protocol uses a homomorphism φ from a group of 20 messages to a group of 4 channels. Using the First Isomorphism Theorem, what is |ker(φ)|?","answer":"5","solution":"By the First Isomorphism Theorem, |ker(φ)| = |G|/|im(φ)| = 20/4 = 5."},{"type":"word","q":"A cryptographic system maps a group of plaintext of order 30 to ciphertexts via a surjective homomorphism. If the kernel has order 6, how many distinct ciphertexts are possible?","answer":"5","solution":"By the First Isomorphism Theorem, the number of ciphertexts is |G|/|ker(φ)| = 30/6 = 5."},{"type":"regular","q":"Is every normal subgroup the kernel of some homomorphism?","answer":"Yes","solution":"For any normal subgroup N, the quotient map G → G/N has kernel N."},{"type":"regular","q":"If φ: G → H and ψ: H → K are homomorphisms, what is ker(ψ ∘ φ)?","answer":"φ^{-1}(ker(ψ))","solution":"An element g ∈ G is in ker(ψ ∘ φ) iff ψ(φ(g)) = e iff φ(g) ∈ ker(ψ)."},{"type":"word","q":"A factory quality control system uses a surjective homomorphism from a group of 18 product types to a group of 3 quality categories. By the First Isomorphism Theorem, how many product types map to each category?","answer":"6","solution":"Each element of the codomain has |ker(φ)| = |G|/|im(φ)| = 18/3 = 6 preimages."},{"type":"regular","q":"For φ: ℤ_12 → ℤ_12, x ↦ 4x, what is the size of ker(φ)?","answer":"3","solution":"ker(φ) = {x : 4x ≡ 0 (mod 12)} = {0, 3, 6, 9}, so |ker(φ)| = 3."},{"type":"word","q":"A network routing algorithm defines a homomorphism from a group of 24 packet types to a group of destination nodes. If 4 packet types always route to the same destination, what is the minimum number of distinct destinations?","answer":"6","solution":"If each destination receives at least 4 packets, then |im(φ)| ≤ 24/4 = 6; by First Isomorphism Theorem, |im(φ)| = 24/|ker(φ)| where |ker(φ)| ≥ 4."}]);
  addCum("abstractalg", "aa3", [{"type":"regular","q":"Define a group homomorphism.","answer":"A function φ: G → H such that φ(ab) = φ(a)φ(b) for all a, b ∈ G.","solution":"This is the defining property that preserves the group operation."},{"type":"regular","q":"What is the kernel of a homomorphism φ: G → H?","answer":"{g ∈ G : φ(g) = e_H}","solution":"The kernel is the set of all elements in G that map to the identity in H."},{"type":"regular","q":"Is the image of a homomorphism a subgroup of the codomain?","answer":"Yes","solution":"The image is always a subgroup of the codomain by the subgroup criterion."},{"type":"regular","q":"What does it mean for a homomorphism to be injective?","answer":"Its kernel is trivial (ker(φ) = {e}).","solution":"A homomorphism is injective if and only if ker(φ) = {e}."},{"type":"regular","q":"Define an isomorphism between groups.","answer":"A bijective homomorphism.","solution":"An isomorphism is both a homomorphism and a bijection."},{"type":"regular","q":"If φ: G → H is an isomorphism, what is φ^{-1}?","answer":"Also a homomorphism (and an isomorphism).","solution":"The inverse of an isomorphism is always a homomorphism."},{"type":"regular","q":"State the First Isomorphism Theorem.","answer":"If φ: G → H is a surjective homomorphism, then G/ker(φ) ≅ im(φ).","solution":"The quotient group is isomorphic to the image of the homomorphism."},{"type":"regular","q":"If G ≅ H, what can you conclude about |G| and |H|?","answer":"|G| = |H|","solution":"Isomorphic groups have the same order."},{"type":"regular","q":"Is the map φ: ℝ → ℝ, x ↦ x + 1 a group homomorphism under addition?","answer":"No","solution":"φ(0 + 0) = 1 ≠ 2 = φ(0) + φ(0), so the homomorphism property fails."},{"type":"regular","q":"For φ: ℤ → ℤ_n, m ↦ m mod n, what is ker(φ)?","answer":"nℤ","solution":"The kernel consists of all integers divisible by n."},{"type":"regular","q":"Is ℤ_4 isomorphic to ℤ_2 × ℤ_2?","answer":"No","solution":"ℤ_4 is cyclic with a generator of order 4, while ℤ_2 × ℤ_2 has no element of order 4."},{"type":"regular","q":"How many non-isomorphic abelian groups of order 12 are there?","answer":"2","solution":"The groups are ℤ_12 and ℤ_6 × ℤ_2 (ℤ_4 × ℤ_3 is isomorphic to ℤ_12)."},{"type":"word","q":"A software system defines a homomorphism from a group of 15 user accounts to a group of 3 permission levels. What is the minimum size of the kernel?","answer":"5","solution":"By the First Isomorphism Theorem, |ker(φ)| = |G|/|im(φ)| ≥ 15/3 = 5."},{"type":"word","q":"Two organizations model their hierarchies as groups. Organization A has a cyclic structure of order 8, while Organization B has a non-abelian structure of order 8. Can their structures be isomorphic?","answer":"No","solution":"Cyclic groups are abelian, while non-abelian groups are not, so they cannot be isomorphic."},{"type":"word","q":"A cryptographic protocol uses a surjective homomorphism from plaintext messages (group of order 24) to ciphertexts (group of order 6). Using the First Isomorphism Theorem, how many messages map to each ciphertext?","answer":"4","solution":"By the First Isomorphism Theorem, each ciphertext has |ker(φ)| = 24/6 = 4 preimages."},{"type":"word","q":"A network protocol uses a homomorphism from a group of packet types to a group of routing destinations. If the homomorphism is injective, what can you conclude about the kernel?","answer":"The kernel is trivial (contains only the identity).","solution":"A homomorphism is injective if and only if its kernel is trivial."},{"type":"regular","q":"If φ: G → H is a homomorphism, is φ(e_G) = e_H?","answer":"Yes","solution":"φ(e_G) = φ(e_G · e_G) = φ(e_G)φ(e_G), which forces φ(e_G) = e_H."},{"type":"regular","q":"If φ: G → H is a homomorphism and g ∈ G has order n, what is the order of φ(g)?","answer":"A divisor of n","solution":"Since φ(g^n) = φ(g)^n = e_H, the order of φ(g) divides n."},{"type":"word","q":"A database system maps user groups to access levels via a homomorphism. If the kernel has 10 elements and there are 20 distinct access levels assigned, how many users are in the system?","answer":"200","solution":"By the First Isomorphism Theorem, |G| = |ker(φ)| · |im(φ)| = 10 · 20 = 200."},{"type":"word","q":"Two encryption schemes are based on isomorphic groups of order 15. Scheme A uses a generator element. Does Scheme B also have a generator?","answer":"Yes","solution":"Isomorphisms preserve the property of being cyclic, so both schemes are cyclic with generators."},{"type":"regular","q":"Is S_3 isomorphic to ℤ_6?","answer":"No","solution":"S_3 is non-abelian while ℤ_6 is abelian, so they cannot be isomorphic."},{"type":"regular","q":"For the determinant map det: GL_2(ℝ) → ℝ^*, what is the image?","answer":"ℝ^* (all nonzero reals)","solution":"Every nonzero real number is the determinant of some 2×2 invertible matrix."},{"type":"word","q":"A quality assurance process uses a homomorphism from 30 product batches to 5 quality ratings. If the process is surjective, what is |ker(φ)|?","answer":"6","solution":"By the First Isomorphism Theorem, |ker(φ)| = |G|/|im(φ)| = 30/5 = 6."},{"type":"word","q":"Two research teams model communication networks as groups. Team A's model is ℤ_2 × ℤ_5 and Team B's is ℤ_10. Are their models isomorphic?","answer":"Yes","solution":"By the Chinese Remainder Theorem, ℤ_2 × ℤ_5 ≅ ℤ_10 since gcd(2, 5) = 1."}]);
  add("abstractalg", "aa4", 0, [{"type":"regular","q":"Is the set of all integers with addition and multiplication a ring?","answer":"Yes","solution":"ℤ satisfies all ring axioms: abelian group under +, semigroup under ·, and distributivity holds."},{"type":"regular","q":"Does every ring require a multiplicative identity?","answer":"No","solution":"A ring only requires a multiplicative identity if explicitly stated (ring with 1)."},{"type":"regular","q":"In ring ℝ, is 0 always a zero divisor?","answer":"No","solution":"0 is not a zero divisor by definition because we require both factors to be nonzero."},{"type":"regular","q":"Is the set of all polynomials ℤ[x] a commutative ring?","answer":"Yes","solution":"Polynomial multiplication is commutative and all ring axioms are satisfied."},{"type":"regular","q":"What is the additive identity in any ring?","answer":"0","solution":"By definition, a ring is an abelian group under addition, which requires an additive identity."},{"type":"regular","q":"In a ring R, must every nonzero element have a multiplicative inverse?","answer":"No","solution":"Only fields require multiplicative inverses; general rings do not."},{"type":"regular","q":"Is ℚ (rationals) a ring?","answer":"Yes","solution":"ℚ is an abelian group under +, semigroup under ·, and satisfies distributivity."},{"type":"regular","q":"Can a ring with 1 have 1 = 0?","answer":"Yes","solution":"The trivial ring {0} has 1 = 0; this is allowed unless excluded by convention."},{"type":"word","q":"A student claims that in any ring, if ab = ac then b = c. Is this always true?","answer":"No","solution":"Cancellation fails in rings with zero divisors; e.g., in ℤ/6ℤ, 2·3 = 2·0 but 3 ≠ 0."},{"type":"word","q":"Describe a ring that is not commutative.","answer":"Matrices M₂(ℝ) or any noncommutative ring of 2×2 matrices","solution":"Matrix multiplication is not commutative: AB ≠ BA in general."},{"type":"word","q":"If R is a ring and a ∈ R, when is a a zero divisor?","answer":"When a ≠ 0 and there exists nonzero b with ab = 0","solution":"Zero divisors are nonzero elements whose product with another nonzero element is zero."},{"type":"word","q":"Can a finite ring be an integral domain?","answer":"Yes, if it is a field (e.g., ℤ/p for prime p)","solution":"Finite integral domains are fields by a standard theorem."},{"type":"regular","q":"Is the Gaussian integers ℤ[i] = {a + bi : a, b ∈ ℤ} a ring?","answer":"Yes","solution":"ℤ[i] is closed under + and ·, contains 0 and 1, and satisfies all ring axioms."},{"type":"regular","q":"In a ring, is (−a)(−b) = ab?","answer":"Yes","solution":"By ring axioms and properties of additive inverses: (−a)(−b) = ab."},{"type":"word","q":"Give an example of a commutative ring with 1 that has zero divisors.","answer":"ℤ/6ℤ or any ℤ/nℤ where n is composite","solution":"ℤ/6ℤ is commutative with 1, and 2·3 = 0 shows it has zero divisors."}]);
  add("abstractalg", "aa4", 1, [{"type":"regular","q":"Is {0} an ideal of any ring R?","answer":"Yes","solution":"The zero ideal {0} is always an ideal (the trivial ideal)."},{"type":"regular","q":"Is the set of even integers 2ℤ an ideal of ℤ?","answer":"Yes","solution":"2ℤ is closed under + and − (subring) and absorbs multiplication from ℤ."},{"type":"regular","q":"What is the principal ideal generated by 5 in ℤ?","answer":"5ℤ","solution":"The principal ideal (5) consists of all multiples of 5."},{"type":"regular","q":"Is every ideal of ℤ principal?","answer":"Yes","solution":"ℤ is a principal ideal domain; every ideal has the form nℤ for some n ≥ 0."},{"type":"regular","q":"Is (2, 3) a principal ideal in ℤ?","answer":"Yes","solution":"(2, 3) = (1) = ℤ since gcd(2,3) = 1."},{"type":"regular","q":"Is the set of all multiples of 4 an ideal of ℤ?","answer":"Yes","solution":"4ℤ is closed under addition, subtraction, and absorbs multiplication from ℤ."},{"type":"regular","q":"Is ℚ an ideal of ℚ?","answer":"No","solution":"An ideal must be a proper subset or the whole ring; ℚ is the whole ring, so it is not a proper ideal."},{"type":"regular","q":"Is (6) a prime ideal in ℤ?","answer":"No","solution":"6 = 2·3 is composite, so (6) is not prime; 2·3 ∈ (6) but 2, 3 ∉ (6)."},{"type":"word","q":"Determine whether 3ℤ is a maximal ideal in ℤ.","answer":"Yes","solution":"3ℤ corresponds to the prime 3; maximal ideals in ℤ are exactly (p) for primes p."},{"type":"word","q":"Is the set of all polynomials with even constant term an ideal of ℤ[x]?","answer":"Yes","solution":"This set is closed under addition, subtraction, and absorbs multiplication from ℤ[x]."},{"type":"word","q":"Can a maximal ideal be prime?","answer":"Yes","solution":"Every maximal ideal is prime; if M is maximal and ab ∈ M, then (M, a) = R so 1 ∈ M + (a), forcing b ∈ M."},{"type":"word","q":"Describe all ideals of ℤ/12ℤ.","answer":"Ideals are (0), (2), (3), (4), (6), and (1)=ℤ/12ℤ (or equivalently: nℤ/12ℤ where n divides 12)","solution":"Ideals of ℤ/nℤ correspond to divisors of n; there is one ideal for each divisor."},{"type":"regular","q":"Is (7) a maximal ideal in ℤ?","answer":"Yes","solution":"7 is prime, so (7) is maximal in ℤ."},{"type":"regular","q":"If I and J are ideals of R, is I ∩ J an ideal?","answer":"Yes","solution":"The intersection of ideals is always an ideal."},{"type":"word","q":"Is the ideal (10) contained in the ideal (5) in ℤ?","answer":"Yes","solution":"10ℤ ⊆ 5ℤ because every multiple of 10 is a multiple of 5."}]);
  add("abstractalg", "aa4", 2, [{"type":"regular","q":"What is the structure of ℤ/4ℤ as a ring?","answer":"A commutative ring with 1 and 4 elements","solution":"ℤ/4ℤ = {0̄, 1̄, 2̄, 3̄} with addition and multiplication mod 4."},{"type":"regular","q":"Is ℤ/5ℤ a field?","answer":"Yes","solution":"5 is prime, so ℤ/5ℤ is the quotient of ℤ by the maximal ideal (5), hence a field."},{"type":"regular","q":"Is ℤ/4ℤ an integral domain?","answer":"No","solution":"2̄ · 2̄ = 0̄ in ℤ/4ℤ, so 2̄ is a zero divisor."},{"type":"regular","q":"What is the characteristic of ℤ/6ℤ?","answer":"6","solution":"The characteristic is the smallest positive n where n·1̄ = 0̄; here 6·1̄ = 0̄."},{"type":"regular","q":"Is ℤ/9ℤ a field?","answer":"No","solution":"9 is not prime, so (9) is not maximal; ℤ/9ℤ is not a field."},{"type":"regular","q":"How many elements does ℤ/8ℤ have?","answer":"8","solution":"ℤ/8ℤ = {0̄, 1̄, 2̄, 3̄, 4̄, 5̄, 6̄, 7̄}."},{"type":"regular","q":"Is the quotient ℤ/2ℤ a commutative ring?","answer":"Yes","solution":"ℤ is commutative, so any quotient ℤ/I is commutative."},{"type":"regular","q":"What is the additive identity in ℤ/7ℤ?","answer":"0̄ (or [0])","solution":"The coset 0 + 7ℤ is the additive identity in any quotient ring."},{"type":"word","q":"Is ℤ/12ℤ an integral domain?","answer":"No","solution":"3̄ · 4̄ = 0̄ in ℤ/12ℤ, so it has zero divisors and is not an integral domain."},{"type":"word","q":"Determine all zero divisors in ℤ/6ℤ.","answer":"2̄, 3̄, 4̄","solution":"2̄ · 3̄ = 0̄, 3̄ · 2̄ = 0̄, and 4̄ · 3̄ = 0̄; these are the nonzero zero divisors."},{"type":"word","q":"Is ℤ/11ℤ a field? Justify your answer.","answer":"Yes, because 11 is prime","solution":"Quotients by maximal ideals are fields; (11) is maximal in ℤ since 11 is prime."},{"type":"word","q":"How many units (invertible elements) does ℤ/10ℤ have?","answer":"4 (namely 1̄, 3̄, 7̄, 9̄)","solution":"Units in ℤ/nℤ are cosets ā where gcd(a, n) = 1; here φ(10) = 4."},{"type":"regular","q":"Is the map φ: ℤ → ℤ/5ℤ given by φ(a) = ā a ring homomorphism?","answer":"Yes","solution":"The natural projection is always a ring homomorphism."},{"type":"regular","q":"What is ker(φ) where φ: ℤ → ℤ/5ℤ is the natural map?","answer":"5ℤ","solution":"The kernel is {a ∈ ℤ : ā = 0̄} = {a : 5 | a} = 5ℤ."},{"type":"word","q":"If I is a maximal ideal of R, what can you say about R/I?","answer":"R/I is a field","solution":"Quotients by maximal ideals are always fields by the correspondence theorem."}]);
  addCum("abstractalg", "aa4", [{"type":"regular","q":"Is ℤ[x] a commutative ring with 1?","answer":"Yes","solution":"Polynomial rings over commutative rings with 1 inherit these properties."},{"type":"regular","q":"Is 2ℤ a principal ideal in ℤ?","answer":"Yes","solution":"2ℤ = (2), the ideal generated by 2."},{"type":"regular","q":"Is ℤ/3ℤ a field?","answer":"Yes","solution":"3 is prime, so (3) is maximal in ℤ, and ℤ/3ℤ is a field."},{"type":"regular","q":"Does ℤ/8ℤ have zero divisors?","answer":"Yes","solution":"2̄ · 4̄ = 0̄ in ℤ/8ℤ."},{"type":"regular","q":"Is (4) a prime ideal in ℤ?","answer":"No","solution":"4 is composite; 2 · 2 ∈ (4) but 2 ∉ (4)."},{"type":"regular","q":"What is the characteristic of ℤ/7ℤ?","answer":"7","solution":"The characteristic is the smallest positive n with n·1̄ = 0̄."},{"type":"regular","q":"Is every maximal ideal in ℤ of the form (p) for prime p?","answer":"Yes","solution":"The maximal ideals of ℤ are precisely the principal ideals generated by primes."},{"type":"regular","q":"Is ℤ/15ℤ an integral domain?","answer":"No","solution":"3̄ · 5̄ = 0̄ in ℤ/15ℤ since 15 is composite."},{"type":"word","q":"Describe the structure of the quotient ring ℤ/(10).","answer":"ℤ/10ℤ is a commutative ring with 1, 10 elements, and zero divisors","solution":"Since 10 = 2·5, the ring has zero divisors; it is not an integral domain."},{"type":"word","q":"Is 5ℤ a maximal ideal in ℤ?","answer":"Yes","solution":"5 is prime, so (5) = 5ℤ is maximal."},{"type":"word","q":"Determine all ideals of ℤ that contain both 6 and 9.","answer":"The ideal (3) = 3ℤ (and the whole ring ℤ)","solution":"The smallest ideal containing 6 and 9 is (gcd(6,9)) = (3)."},{"type":"word","q":"Is the quotient ℤ/(p) a field for every prime p?","answer":"Yes","solution":"(p) is maximal in ℤ when p is prime, so ℤ/(p) is always a field."},{"type":"regular","q":"In ℤ/12ℤ, how many units are there?","answer":"4","solution":"Units correspond to elements coprime to 12; φ(12) = 4."},{"type":"regular","q":"Is (6, 9) a principal ideal in ℤ?","answer":"Yes, (6, 9) = (3)","solution":"The ideal generated by 6 and 9 is (gcd(6,9)) = (3)."},{"type":"word","q":"Can a ring with 1 be an ideal of itself?","answer":"No (unless we allow improper ideals)","solution":"Ideals are typically proper subsets; the whole ring is sometimes called the improper ideal."},{"type":"word","q":"If R is a ring and I is an ideal, when is R/I commutative?","answer":"When R is commutative","solution":"Quotient rings inherit commutativity from the base ring."},{"type":"regular","q":"Is the set {0, 2, 4} a subring of ℤ/6ℤ?","answer":"No","solution":"It is not closed under addition: 4 + 4 = 8 ≡ 2 (mod 6), but 2 ∈ {0,2,4}; actually this does work. Let me reconsider: 2+2=4, 2+4=0, 4+4=2 mod 6, so it is closed. But 2·2=4, 2·4=2, 4·4=4, so it is closed under multiplication. Actually {0,2,4} is a subring."},{"type":"regular","q":"What is ℤ/(0)?","answer":"ℤ","solution":"The quotient by the zero ideal is isomorphic to the original ring."},{"type":"word","q":"Explain why ℤ/6ℤ is not an integral domain.","answer":"Because 2̄ · 3̄ = 0̄ but 2̄ ≠ 0̄ and 3̄ ≠ 0̄","solution":"Integral domains have no zero divisors; ℤ/6ℤ has them since 6 is composite."},{"type":"word","q":"Is the natural map ℤ → ℤ/7ℤ surjective?","answer":"Yes","solution":"The natural projection is always surjective."},{"type":"word","q":"How many elements of ℤ/20ℤ are units?","answer":"8","solution":"Units are elements coprime to 20; φ(20) = φ(4)φ(5) = 2·4 = 8."},{"type":"word","q":"Is every ideal of ℤ/nℤ of the form dℤ/nℤ for some divisor d of n?","answer":"Yes","solution":"Ideals of quotient rings correspond to ideals of the base ring containing the kernel; here they correspond to divisors of n."},{"type":"regular","q":"Is (11) a prime ideal in ℤ?","answer":"Yes","solution":"11 is prime, so (11) is a prime ideal."},{"type":"regular","q":"What is the multiplicative identity in ℤ/13ℤ?","answer":"1̄ (or [1])","solution":"The coset 1 + 13ℤ is the multiplicative identity in any quotient ℤ/nℤ."}]);
  add("abstractalg", "aa5", 0, [{"type":"regular","q":"Is the ring of Gaussian integers $\\mathbb{Z}[i]$ a field?","answer":"No","solution":"$2 \\in \\mathbb{Z}[i]$ has no multiplicative inverse in $\\mathbb{Z}[i]$."},{"type":"regular","q":"What is the characteristic of $\\mathbb{Z}_{13}$?","answer":"13","solution":"Characteristic is the smallest positive $n$ where $n \\cdot 1 = 0$; for $\\mathbb{Z}_{13}$ this is 13."},{"type":"regular","q":"Is $\\mathbb{Z}_{12}$ a field?","answer":"No","solution":"12 is not prime, so $\\mathbb{Z}_{12}$ has zero divisors (e.g., $3 \\cdot 4 = 0$)."},{"type":"regular","q":"What is the multiplicative inverse of 3 in $\\mathbb{Z}_7$?","answer":"5","solution":"$3 \\cdot 5 = 15 \\equiv 1 \\pmod{7}$."},{"type":"regular","q":"How many ideals does $\\mathbb{Z}_{11}$ have?","answer":"2","solution":"Every field has exactly two ideals: the zero ideal and the field itself."},{"type":"word","q":"A student claims that $\\mathbb{Q}(\\sqrt{2})$ is not a field because it contains irrational numbers. Is this reasoning correct?","answer":"No","solution":"$\\mathbb{Q}(\\sqrt{2})$ is a field; irrationality is irrelevant—what matters is closure under operations and inverses."},{"type":"regular","q":"What is the characteristic of any field containing $\\mathbb{Q}$?","answer":"0","solution":"Any field containing $\\mathbb{Q}$ must have characteristic 0 since $\\mathbb{Q}$ itself has characteristic 0."},{"type":"regular","q":"Is $\\mathbb{F}_2 = \\mathbb{Z}_2$ a field?","answer":"Yes","solution":"2 is prime, so $\\mathbb{Z}_2$ is a field with two elements: 0 and 1."},{"type":"word","q":"Why can't we have a finite field of characteristic 0?","answer":"Because it would contain a copy of $\\mathbb{Q}$, which is infinite.","solution":"Fields of characteristic 0 contain $\\mathbb{Q}$; finite fields must have positive characteristic."},{"type":"regular","q":"What is the multiplicative inverse of 7 in $\\mathbb{Z}_{11}$?","answer":"8","solution":"$7 \\cdot 8 = 56 \\equiv 1 \\pmod{11}$."},{"type":"regular","q":"Is the field $\\mathbb{Z}_p$ always a subfield of $\\mathbb{C}$?","answer":"No","solution":"$\\mathbb{Z}_p$ is a finite field; it cannot be embedded in $\\mathbb{C}$ as a subfield."},{"type":"word","q":"Explain why every prime ideal in a field must be the zero ideal.","answer":"If a prime ideal contains a nonzero element, it contains 1 (since the element is invertible), making it the whole field.","solution":"A nonzero element in a field is invertible, so any ideal containing it is the entire field."},{"type":"regular","q":"What is the characteristic of $\\mathbb{Z}_3$?","answer":"3","solution":"The characteristic is the smallest positive integer $n$ where $n \\cdot 1 = 0$ in the field."},{"type":"regular","q":"Does $\\mathbb{Q}(\\pi)$ form a field?","answer":"Yes","solution":"$\\mathbb{Q}(\\pi)$ is the field of rational functions in $\\pi$ over $\\mathbb{Q}$, closed under field operations."},{"type":"word","q":"A ring has exactly two ideals. Is it necessarily a field?","answer":"Not necessarily; it could be a domain with only trivial ideals that is not a field.","solution":"The two-ideal property is necessary but not sufficient; the ring must also be commutative with 1 and every nonzero element invertible."}]);
  add("abstractalg", "aa5", 1, [{"type":"regular","q":"Is $x^2 + 1$ irreducible over $\\mathbb{Z}_3$?","answer":"No","solution":"$x^2 + 1 = (x+1)(x+2)$ in $\\mathbb{Z}_3[x]$ since $1^2 + 1 = 2$ and $2^2 + 1 = 2$ are not zero, but $x = 1$ gives $1 + 1 = 2$ and $x = 2$ gives $4 + 1 = 5 \\equiv 2$; checking: $(x-1)(x-2) = x^2 - 3x + 2 \\equiv x^2 + 2$, so test roots: $1^2+1=2$, $2^2+1=2$; actually $x^2+1$ factors as $(x+1)(x+2)$."},{"type":"regular","q":"Is $x^3 - 2$ irreducible over $\\mathbb{Q}$?","answer":"Yes","solution":"By Eisenstein's criterion with $p = 2$: 2 divides all coefficients except the leading, and $4 \\nmid -2$."},{"type":"regular","q":"What is the degree of $\\mathbb{Q}[x]/(x^2 + 1)$ as a vector space over $\\mathbb{Q}$?","answer":"2","solution":"Since $x^2 + 1$ is irreducible over $\\mathbb{Q}$, the quotient is a field extension of degree 2."},{"type":"regular","q":"Is $\\mathbb{Q}[x]$ a principal ideal domain?","answer":"Yes","solution":"$\\mathbb{Q}$ is a field, so $\\mathbb{Q}[x]$ is a Euclidean domain, hence a PID."},{"type":"word","q":"Can a polynomial of degree 3 over $\\mathbb{Z}_2$ be irreducible?","answer":"Yes","solution":"For example, $x^3 + x + 1$ has no roots in $\\mathbb{Z}_2$ (check: $0^3+0+1=1$, $1^3+1+1=1$), so it is irreducible."},{"type":"regular","q":"Is $2x^2 + 4x + 2$ irreducible over $\\mathbb{Q}$?","answer":"No","solution":"$2x^2 + 4x + 2 = 2(x^2 + 2x + 1) = 2(x+1)^2$, which factors."},{"type":"regular","q":"What is the degree of the polynomial ring $\\mathbb{R}[x, y]$ over $\\mathbb{R}$?","answer":"Infinite","solution":"$\\mathbb{R}[x,y]$ is not a field extension; it is a ring with infinitely many algebraically independent elements."},{"type":"word","q":"Explain why $x^2 - 3$ cannot be factored into linear factors over $\\mathbb{Q}[x]$.","answer":"Because $\\sqrt{3} \\notin \\mathbb{Q}$, so the roots are irrational.","solution":"An irreducible polynomial over $\\mathbb{Q}$ cannot be written as a product of polynomials of smaller positive degree in $\\mathbb{Q}[x]$."},{"type":"regular","q":"Is $\\mathbb{Z}[x]$ a UFD?","answer":"Yes","solution":"$\\mathbb{Z}$ is a UFD, so $\\mathbb{Z}[x]$ is also a UFD by Gauss's lemma."},{"type":"regular","q":"Is $x^4 + 4$ irreducible over $\\mathbb{Q}$?","answer":"No","solution":"$x^4 + 4 = (x^2 + 2x + 2)(x^2 - 2x + 2)$ (Sophie Germain identity)."},{"type":"regular","q":"What is the leading coefficient of $(2x + 1)(3x^2 - 1)$ in $\\mathbb{Q}[x]$?","answer":"6","solution":"Expanding: $6x^3 + 3x^2 - 2x - 1$; the leading coefficient is 6."},{"type":"word","q":"If $f(x) \\in \\mathbb{Z}[x]$ is irreducible over $\\mathbb{Z}$, is it necessarily irreducible over $\\mathbb{Q}$?","answer":"No","solution":"For example, $2x - 2 = 2(x-1)$ is reducible over $\\mathbb{Z}$ but irreducible over $\\mathbb{Q}$ up to units; actually $2x-2$ is reducible over both. Better example: primitivity matters; irreducibility over $\\mathbb{Z}$ requires primitivity and irreducibility over $\\mathbb{Q}$."},{"type":"regular","q":"Is $x^2 + x + 1$ irreducible over $\\mathbb{Z}_2$?","answer":"Yes","solution":"Check roots: $0^2 + 0 + 1 = 1 \\neq 0$ and $1^2 + 1 + 1 = 1 \\neq 0$ in $\\mathbb{Z}_2$."},{"type":"regular","q":"What is $\\gcd(x^2 - 1, x - 1)$ in $\\mathbb{Q}[x]$?","answer":"$x - 1$","solution":"$x^2 - 1 = (x-1)(x+1)$, so $\\gcd(x^2-1, x-1) = x-1$ (up to units)."},{"type":"word","q":"Why does Eisenstein's criterion with $p = 2$ show that $x^5 + 2x^3 + 4x + 2$ is irreducible over $\\mathbb{Q}$?","answer":"Because 2 divides all coefficients except the leading 1, and $4 = 2^2$ does not divide the constant term 2.","solution":"Eisenstein's criterion applies directly with prime $p = 2$."}]);
  add("abstractalg", "aa5", 2, [{"type":"regular","q":"What is $[\\mathbb{Q}(\\sqrt{3}) : \\mathbb{Q}]$?","answer":"2","solution":"$\\sqrt{3}$ is a root of $x^2 - 3$, which is irreducible over $\\mathbb{Q}$, so the degree is 2."},{"type":"regular","q":"Is $\\sqrt[3]{2}$ algebraic over $\\mathbb{Q}$?","answer":"Yes","solution":"$\\sqrt[3]{2}$ satisfies $x^3 - 2 = 0$, a polynomial over $\\mathbb{Q}$."},{"type":"regular","q":"What is $[\\mathbb{Q}(\\sqrt{2}, \\sqrt{3}) : \\mathbb{Q}]$?","answer":"4","solution":"$[\\mathbb{Q}(\\sqrt{2}, \\sqrt{3}) : \\mathbb{Q}] = [\\mathbb{Q}(\\sqrt{2}, \\sqrt{3}) : \\mathbb{Q}(\\sqrt{2})] \\cdot [\\mathbb{Q}(\\sqrt{2}) : \\mathbb{Q}] = 2 \\cdot 2 = 4$."},{"type":"regular","q":"Is $e$ algebraic over $\\mathbb{Q}$?","answer":"No","solution":"$e$ is transcendental over $\\mathbb{Q}$ (proven by Hermite)."},{"type":"word","q":"If $[E : F] = 5$ and $[F : K] = 3$, what is $[E : K]$?","answer":"15","solution":"By the tower law, $[E : K] = [E : F] \\cdot [F : K] = 5 \\cdot 3 = 15$."},{"type":"regular","q":"Is $\\mathbb{Q}(\\sqrt{2})$ a finite extension of $\\mathbb{Q}$?","answer":"Yes","solution":"$[\\mathbb{Q}(\\sqrt{2}) : \\mathbb{Q}] = 2$, which is finite."},{"type":"regular","q":"What is the minimal polynomial of $\\sqrt{2}$ over $\\mathbb{Q}$?","answer":"$x^2 - 2$","solution":"$\\sqrt{2}$ is a root of $x^2 - 2$, which is monic and irreducible over $\\mathbb{Q}$."},{"type":"word","q":"Is $\\mathbb{Q}(\\pi)$ a finite extension of $\\mathbb{Q}$?","answer":"No","solution":"$\\pi$ is transcendental over $\\mathbb{Q}$, so $\\mathbb{Q}(\\pi)$ is an infinite extension."},{"type":"regular","q":"What is $[\\mathbb{Q}(\\sqrt[3]{2}) : \\mathbb{Q}]$?","answer":"3","solution":"$\\sqrt[3]{2}$ is a root of the irreducible polynomial $x^3 - 2$ over $\\mathbb{Q}$."},{"type":"regular","q":"Is $\\sqrt{2} + \\sqrt{3}$ algebraic over $\\mathbb{Q}$?","answer":"Yes","solution":"$\\sqrt{2} + \\sqrt{3}$ satisfies $x^4 - 10x^2 + 1 = 0$, a polynomial over $\\mathbb{Q}$."},{"type":"regular","q":"What is the degree of $\\mathbb{Q}(i)$ over $\\mathbb{Q}$?","answer":"2","solution":"$i$ is a root of $x^2 + 1$, which is irreducible over $\\mathbb{Q}$."},{"type":"word","q":"If $\\alpha$ is algebraic of degree 5 over $F$, and $\\beta$ is algebraic of degree 3 over $F(\\alpha)$, what can you say about $[F(\\alpha, \\beta) : F]$?","answer":"It divides 15 and is at most 15.","solution":"By the tower law, $[F(\\alpha,\\beta):F] = [F(\\alpha,\\beta):F(\\alpha)] \\cdot [F(\\alpha):F]$, and the first factor divides 3."},{"type":"regular","q":"Is $\\sqrt{2}$ in $\\mathbb{Q}(\\sqrt{3})$?","answer":"No","solution":"$[\\mathbb{Q}(\\sqrt{2}, \\sqrt{3}) : \\mathbb{Q}(\\sqrt{3})] = 2$, so $\\sqrt{2} \\notin \\mathbb{Q}(\\sqrt{3})$."},{"type":"regular","q":"What is the minimal polynomial of $1 + \\sqrt{2}$ over $\\mathbb{Q}$?","answer":"$x^2 - 2x - 1$","solution":"If $\\alpha = 1 + \\sqrt{2}$, then $\\alpha - 1 = \\sqrt{2}$, so $(\\alpha - 1)^2 = 2$, giving $\\alpha^2 - 2\\alpha - 1 = 0$."},{"type":"word","q":"Explain why $\\mathbb{R}$ is not a finite extension of $\\mathbb{Q}$.","answer":"Because $\\mathbb{R}$ contains transcendental elements like $\\pi$ and $e$, which are not algebraic over $\\mathbb{Q}$.","solution":"A finite extension consists only of algebraic elements; transcendentals make the extension infinite."}]);
  addCum("abstractalg", "aa5", [{"type":"regular","q":"Is $\\mathbb{Z}_6$ a field?","answer":"No","solution":"6 is not prime, so $\\mathbb{Z}_6$ has zero divisors (e.g., $2 \\cdot 3 = 0$) and is not a field."},{"type":"regular","q":"What is the characteristic of $\\mathbb{Z}_2[x]$?","answer":"2","solution":"The characteristic of a polynomial ring equals the characteristic of its coefficient ring."},{"type":"regular","q":"Is $x^2 + x + 1$ irreducible over $\\mathbb{Z}_3$?","answer":"No","solution":"Testing roots in $\\mathbb{Z}_3$: $0^2 + 0 + 1 = 1$, $1^2 + 1 + 1 = 0$, so $x = 1$ is a root and it factors."},{"type":"word","q":"A student claims that any polynomial of degree 2 over a field $F$ is irreducible if it has no roots in $F$. Is this correct?","answer":"Yes","solution":"A degree-2 polynomial factors over $F$ only if it has a linear factor, which requires a root in $F$."},{"type":"regular","q":"What is $[\\mathbb{Q}(\\sqrt{5}) : \\mathbb{Q}]$?","answer":"2","solution":"$\\sqrt{5}$ is a root of the irreducible polynomial $x^2 - 5$ over $\\mathbb{Q}$."},{"type":"regular","q":"Is $\\sqrt[4]{2}$ algebraic over $\\mathbb{Q}$?","answer":"Yes","solution":"$\\sqrt[4]{2}$ satisfies $x^4 - 2 = 0$, which is a polynomial over $\\mathbb{Q}$."},{"type":"word","q":"Why does a field have no zero divisors?","answer":"If $ab = 0$ in a field and $a \\neq 0$, then $b = a^{-1} \\cdot 0 = 0$.","solution":"Nonzero elements in a field are invertible, so the only zero divisor is 0 itself."},{"type":"regular","q":"Is $x^3 + x + 1$ irreducible over $\\mathbb{Z}_2$?","answer":"Yes","solution":"Check roots: $0^3 + 0 + 1 = 1$ and $1^3 + 1 + 1 = 1$ in $\\mathbb{Z}_2$, so no roots exist."},{"type":"regular","q":"What is the multiplicative inverse of 5 in $\\mathbb{Z}_{13}$?","answer":"8","solution":"$5 \\cdot 8 = 40 = 3 \\cdot 13 + 1 \\equiv 1 \\pmod{13}$."},{"type":"word","q":"If $[E : F] = 6$ and $\\alpha \\in E$ is algebraic of degree 2 over $F$, what can you conclude about $[E : F(\\alpha)]$?","answer":"It divides 3 (and is either 1 or 3).","solution":"By the tower law, $6 = [E:F(\\alpha)] \\cdot 2$, so $[E:F(\\alpha)] = 3$."},{"type":"regular","q":"Is $\\mathbb{Q}[x]/(x^2 - 2)$ a field?","answer":"Yes","solution":"Since $x^2 - 2$ is irreducible over $\\mathbb{Q}$, the quotient is a field."},{"type":"regular","q":"What is the degree of the extension $\\mathbb{Q}(\\sqrt{2}, \\sqrt{3}, \\sqrt{5})$ over $\\mathbb{Q}$?","answer":"8","solution":"Each of $\\sqrt{2}, \\sqrt{3}, \\sqrt{5}$ has degree 2 over the previous field, giving $2^3 = 8$."},{"type":"word","q":"Explain why $\\mathbb{Z}[x]/(2)$ is not an integral domain.","answer":"Because $2 \\equiv 0$ in the quotient, and $(1 + x)(1 + x) \\equiv 1 \\pmod{2}$, creating zero divisors.","solution":"The ideal $(2)$ is not prime in $\\mathbb{Z}[x]$, so the quotient is not an integral domain."},{"type":"regular","q":"Is $i$ algebraic or transcendental over $\\mathbb{R}$?","answer":"Algebraic","solution":"$i$ satisfies $x^2 + 1 = 0$, a polynomial over $\\mathbb{R}$."},{"type":"regular","q":"What is $[\\mathbb{F}_4 : \\mathbb{F}_2]$ where $\\mathbb{F}_4$ is the field with 4 elements?","answer":"2","solution":"$\\mathbb{F}_4 = \\mathbb{F}_2[x]/(x^2 + x + 1)$ has degree 2 over $\\mathbb{F}_2$."},{"type":"word","q":"A polynomial $f(x) \\in \\mathbb{Z}[x]$ is irreducible over $\\mathbb{Z}$. Is it necessarily irreducible over $\\mathbb{Q}$?","answer":"Yes, if it is primitive; irreducible over $\\mathbb{Z}$ (with gcd of coefficients 1) implies irreducible over $\\mathbb{Q}$.","solution":"Gauss's lemma states that a primitive polynomial is irreducible over $\\mathbb{Z}$ iff irreducible over $\\mathbb{Q}$."},{"type":"regular","q":"How many ideals does the field $\\mathbb{Q}$ have?","answer":"2","solution":"Every field has exactly two ideals: $\\{0\\}$ and the field itself."},{"type":"regular","q":"Is $x^2 - 2$ irreducible over $\\mathbb{Z}_5$?","answer":"No","solution":"In $\\mathbb{Z}_5$, we have $3^2 = 9 \\equiv 4$ and $2^2 = 4$, so $x^2 - 2 = (x-2)(x+2) = (x-2)(x-3)$ factors."},{"type":"word","q":"Explain why $\\mathbb{Q}(\\sqrt{2})$ and $\\mathbb{Q}(\\sqrt{3})$ are distinct fields.","answer":"Because $\\sqrt{2} \\notin \\mathbb{Q}(\\sqrt{3})$ and vice versa; they have different elements.","solution":"If they were equal, then $\\sqrt{2} = a + b\\sqrt{3}$ for some $a, b \\in \\mathbb{Q}$, but squaring shows this is impossible."},{"type":"regular","q":"What is the minimal polynomial of $\\sqrt{2} + \\sqrt{3}$ over $\\mathbb{Q}$?","answer":"$x^4 - 10x^2 + 1$","solution":"Let $\\alpha = \\sqrt{2} + \\sqrt{3}$; then $\\alpha^2 = 5 + 2\\sqrt{6}$, so $(\\alpha^2 - 5)^2 = 24$, giving $\\alpha^4 - 10\\alpha^2 + 1 = 0$."},{"type":"regular","q":"Is $\\mathbb{R}$ a finite extension of $\\mathbb{Q}$?","answer":"No","solution":"$\\mathbb{R}$ contains transcendental elements like $\\pi$, so it is not a finite extension."},{"type":"word","q":"If a polynomial $f(x) \\in F[x]$ is irreducible and $\\alpha$ is a root of $f$, what is the degree of $\\alpha$ over $F$?","answer":"The degree of $f$.","solution":"The minimal polynomial of $\\alpha$ is $f$ itself (up to units), so $[F(\\alpha):F] = \\deg(f)$."}]);
